"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["41216"],{44121(e){e.exports=JSON.parse('{"id":"V4-115","slug":"putable-bond","term":"Putable Bond","also_known_as":[],"difficulty":"Intermediate","definition":"A putable bond is a bond that gives the investor the right to sell it back to the issuer at a set price, usually its face value, on specified dates before maturity.","explanation":["A putable bond is the opposite of a callable bond. The put option belongs to the investor, protecting them if interest rates rise or the issuer\u2019s credit weakens.","If interest rates rise, the price of an ordinary bond falls. With a putable bond, the investor can sell the bond back to the issuer at the agreed price and reinvest at the new, higher rates.","For example, an investor holds a ten-year bond paying 4%, putable at 100 after five years. If rates have risen to 6% by then, the investor can return the bond for 100 and buy a new bond paying 6%.","Because the put option is valuable to investors, putable bonds usually pay lower interest rates than comparable bonds without the feature. They are less common than callable bonds. Their prices tend to fall less than ordinary bonds when rates rise, since the put sets a floor on their value."],"note":"","total":1725,"prev":{"slug":"put-option","term":"Put Option"},"next":{"slug":"qualified-dividend","term":"Qualified Dividend"}}')}}]);